(function () {
  // Emulate React's value tracker: the DOM value setter is shadowed by an own
  // property descriptor, so naive `el.value = x` assignments are swallowed and
  // only native-setter + input-event writes take effect.
  function installTracker(el, prop) {
    var proto = Object.getPrototypeOf(el);
    var desc = Object.getOwnPropertyDescriptor(proto, prop);
    var current = el[prop];
    Object.defineProperty(el, prop, {
      configurable: true,
      enumerable: false,
      get: function () { return current; },
      set: function (v) {
        // Swallow direct writes that do not come through the native setter,
        // exactly like a controlled component re-rendering from state.
        current = current;
        desc.set.call(el, current);
      }
    });
    el.__setControlled = function (v) {
      current = v;
      desc.set.call(el, v);
    };
    el.addEventListener('input', function () {
      current = desc.get.call(el);
      var m = document.getElementById('mirror');
      if (m && el.id === 'ctrl-text') { m.textContent = 'mirror: ' + current; }
    });
  }

  installTracker(document.getElementById('ctrl-text'), 'value');
  installTracker(document.getElementById('ctrl-textarea'), 'value');
  installTracker(document.getElementById('ctrl-checkbox'), 'checked');
  installTracker(document.getElementById('ctrl-select'), 'value');
})();

